/** V2-only lead adapter. Normalizes Tourvisor lead data and prepares a bridge to the frozen test helpform handler. */
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
function lead_out(array $d,int $s=200):void{http_response_code($s);echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}function lead_text($v,int $m=500):string{$v=trim(preg_replace('/\s+/u',' ',(string)$v));return mb_substr($v,0,$m,'UTF-8');}function lead_phone($v):string{$d=preg_replace('/\D+/','',trim((string)$v));if(strlen($d)===11&&$d[0]==='8')$d='7'.substr($d,1);return $d!==''?'+'.$d:'';}function lead_money($v):?int{if($v===null||$v==='')return null;$n=(int)round((float)$v);return $n>0?$n:null;}
function lead_build(array $data):array{$phone=lead_phone($data['phone']??'');$tourId=lead_text($data['tourId']??'',200);$errors=[];if(strlen(preg_replace('/\D+/','',$phone))<10)$errors['phone']='Valid phone is required';if($tourId==='')$errors['tourId']='tourId is required';if($errors)return['errors'=>$errors];$lead=['source'=>'poisk-turov-test-v2','name'=>lead_text($data['name']??'',120),'phone'=>$phone,'tourId'=>$tourId,'searchId'=>lead_text($data['searchId']??'',80),'hotel'=>lead_text($data['hotel']??'',240),'country'=>lead_text($data['country']??'',120),'region'=>lead_text($data['region']??'',160),'departure'=>lead_text($data['departure']??'',160),'date'=>lead_text($data['date']??'',40),'nights'=>isset($data['nights'])?(int)$data['nights']:null,'adults'=>isset($data['adults'])?(int)$data['adults']:null,'childs'=>isset($data['childs'])?(int)$data['childs']:null,'meal'=>lead_text($data['meal']??'',160),'roomType'=>lead_text($data['roomType']??'',240),'placement'=>lead_text($data['placement']??'',160),'operator'=>lead_text($data['operator']??'',160),'price'=>lead_money($data['price']??null),'currency'=>lead_text($data['currency']??'RUB',12)?:'RUB','comment'=>lead_text($data['comment']??'',1000),'page'=>lead_text($data['page']??'',500),'createdAt'=>gmdate('c')];$details=['V2 Tourvisor tourId: '.$lead['tourId']];foreach(['searchId'=>'searchId','hotel'=>'Отель','region'=>'Регион','date'=>'Дата','nights'=>'Ночей','meal'=>'Питание','roomType'=>'Номер','placement'=>'Размещение','operator'=>'Оператор'] as $k=>$label){if(!empty($lead[$k]))$details[]=$label.': '.$lead[$k];}if($lead['price'])$details[]='Цена: '.$lead['price'].' '.$lead['currency'];if($lead['comment'])$details[]='Комментарий пользователя: '.$lead['comment'];$bridge=['helpform'=>1,'help_name'=>$lead['name'],'help_phone'=>$lead['phone'],'help_from'=>$lead['departure'],'help_country'=>$lead['country'],'help_text'=>implode('; ',$details),'help_days_from'=>$lead['nights'],'help_days_till'=>$lead['nights'],'help_dates_datepicker'=>$lead['date'],'count_people_help'=>$lead['adults']?:1,'count_child_help'=>$lead['childs']?:0,'yaclient'=>lead_text($data['yaclient']??'',100),'yaclid'=>lead_text($data['yclid']??'',100),'yautmsource'=>lead_text($data['utm_source']??'',160),'yautmmedium'=>lead_text($data['utm_medium']??'',160),'yautmcampaign'=>lead_text($data['utm_campaign']??'',160),'yautmcontent'=>lead_text($data['utm_content']??'',160),'yautmterm'=>lead_text($data['utm_term']??'',160)];return['lead'=>$lead,'bridge'=>$bridge];}
$target=dirname(__DIR__).'/template/search/ajax.php';
if($_SERVER['REQUEST_METHOD']==='GET'){if(isset($_GET['selftest'])){$sample=['name'=>'V2 Selftest','phone'=>'8 (999) 123-45-67','tourId'=>'tv-test-1','searchId'=>'42','hotel'=>'Test Hotel','country'=>'Турция','region'=>'Анталья','departure'=>'Москва','date'=>'2026-09-15','nights'=>7,'adults'=>2,'childs'=>0,'meal'=>'AI','roomType'=>'Standard','placement'=>'DBL','operator'=>'Test Operator','price'=>150000,'comment'=>'bridge self-test'];$built=lead_build($sample);$p=$built['bridge']??[];$checks=['validPhone'=>(($built['lead']['phone']??'')==='+79991234567'),'tourIdMapped'=>(($built['lead']['tourId']??'')==='tv-test-1'),'helpformFlag'=>(($p['helpform']??0)===1),'contactMapped'=>(($p['help_phone']??'')==='+79991234567'),'tourDetailsInText'=>(strpos((string)($p['help_text']??''),'tv-test-1')!==false&&strpos((string)($p['help_text']??''),'Test Hotel')!==false),'legacyTargetPresent'=>is_file($target)];lead_out(['ok'=>!in_array(false,$checks,true),'mode'=>'self-test','writes'=>false,'checks'=>$checks]);}lead_out(['ok'=>true,'adapter'=>'v2-lead-helpform-bridge','mode'=>'dry-run','writes'=>false,'required'=>['phone','tourId'],'bridgeReady'=>is_file($target),'selftest'=>'?selftest=1']);}
if($_SERVER['REQUEST_METHOD']!=='POST')lead_out(['ok'=>false,'error'=>'Method not allowed'],405);$raw=file_get_contents('php://input');$data=json_decode((string)$raw,true);if(!is_array($data))$data=$_POST;$built=lead_build($data);if(!empty($built['errors']))lead_out(['ok'=>false,'error'=>'Validation failed','fields'=>$built['errors']],422);
// Safety gate: do not execute the legacy handler until the deployed self-test passes independently.
lead_out(['ok'=>true,'mode'=>'dry-run','writes'=>false,'lead'=>$built['lead'],'bridge'=>['target'=>'/poisk-turov-test/template/search/ajax.php','ready'=>is_file($target),'payload'=>$built['bridge']]]);
